import { useCallback, useEffect, useState } from 'react'

import type { TodoViewModel } from '../../application/TodoViewModel'
import { useTodosUseCases } from '../useTodosUseCases/useTodosUseCases'

export type TodosState =
  | { readonly status: 'loading' }
  | {
      readonly status: 'loaded'
      readonly todos: TodoViewModel[]
      readonly notice: string | null
      readonly complete: (id: string) => Promise<void>
    }
  | { readonly status: 'failed' }

type Data =
  | { readonly status: 'loading' }
  | { readonly status: 'loaded'; readonly todos: TodoViewModel[]; readonly notice: string | null }
  | { readonly status: 'failed' }

export const useTodos = (): TodosState => {
  const { listTodos, completeTodo } = useTodosUseCases()
  const [data, setData] = useState<Data>({ status: 'loading' })

  useEffect(() => {
    const controller = new AbortController()
    listTodos.execute(controller.signal).then(
      (todos) => setData({ status: 'loaded', todos, notice: null }),
      () => {
        if (!controller.signal.aborted) setData({ status: 'failed' })
      },
    )
    return () => controller.abort()
  }, [listTodos])

  const complete = useCallback(
    async (id: string) => {
      let notice: string | null = null
      let done = false
      try {
        const result = await completeTodo.execute(id)
        done = true
        if (result === 'already-completed') notice = 'This todo is already completed.'
      } catch {
        notice = 'The todo could not be completed.'
      }
      setData((current) =>
        current.status !== 'loaded'
          ? current
          : {
              ...current,
              notice,
              todos: done
                ? current.todos.map((t) => (t.id === id ? { ...t, status: 'done' } : t))
                : current.todos,
            },
      )
    },
    [completeTodo],
  )

  return data.status === 'loaded' ? { ...data, complete } : data
}
